    42	    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
    43	    {
    44	        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, Stopwatch.StartNew());
    45	        var tasa = _limitadorTasa.Intentar(peticion.Ip);
    46	        return tasa.Permitido
    47	            ? await ProcesarEntradaAsync(contexto, peticion, cancellationToken)
    48	            : await RechazarPorTasaAsync(contexto, peticion, tasa.SegundosParaReintentar, cancellationToken);
    49	    }
