    51	    private async Task<IResult> ProcesarEntradaAsync(HttpContext contexto, DatosPeticion peticion, CancellationToken cancellationToken)
    52	    {
    53	        if (!EsJson(contexto.Request.ContentType))
    54	        {
    55	            return RechazarInvalida(peticion, null, StatusCodes.Status415UnsupportedMediaType, TituloTipoNoSoportado);
    56	        }
    57	
    58	        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
    59	        if (cuerpo.ExcedeElLimite)
    60	        {
    61	            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
    62	        }
    63	
    64	        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
    65	        return solicitud.EsValida
    66	            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
    67	            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
    68	    }
