    36	    {
    37	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
    38	        limite.CancelAfter(_restante);
    39	        var cronometro = Stopwatch.StartNew();
    40	        try
    41	        {
