    11	    [
    12	        " una materia ", " una asignatura ", " una nota ", " un estudiante "
    13	    ];
    14	
    15	    private static readonly HashSet<string> MarcadoresDePrimeraPersona = new(StringComparer.Ordinal)
    16	    {
    17	        "mi", "mis", "tengo", "llevo", "voy", "cumplo", "soy", "estoy", "perdi", "gane", "saque", "quede"
    18	    };
    19	
