    22	        "materia", "materias", "asignatura", "asignaturas"
    23	    };
    24	
    25	    private static readonly HashSet<string> TerminosDeDatosAcademicos = new(StringComparer.Ordinal)
    26	    {
    27	        "nota", "notas", "definitiva", "promedio", "corte", "falta", "faltas", "asistencia", "inasistencia",
    28	        "inasistencias", "beca", "habilitar", "materia", "materias", "asignatura", "asignaturas", "perdida",
