    32	    public static ActivacionResumen Evaluar(ContextoUsuario contexto, string pregunta, IReadOnlyList<AsignaturaCatalogo> catalogo)
    33	    {
    34	        if (contexto.Usuario.Rol != Rol.Estudiante)
    35	        {
    36	            return ActivacionResumen.Ninguna;
    37	        }
    38	
    39	        var palabras = TokenizadorTexto.Valores(pregunta);
    40	        if (PrimeraPersona(contexto, palabras) || PuedoConTerminoEspecifico(palabras))
    41	        {
    42	            return new ActivacionResumen(true, []);
    43	        }
    44	
    45	        return new ActivacionResumen(false, CatalogoAsignaturas.CodigosNombrados(pregunta, catalogo, contexto.Directorio.CodigosAsignatura));
