    44	            contexto,
    45	            registro,
    46	            [ConstructorPrompts.MensajeInicial(entrada.Pregunta, entrada.Secciones, entrada.Resumen)],
    47	            entrada.PromptSistema);
    48	        ResultadoConversacion? final = null;
    49	        while (final is null)
