    57	    private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
    58	    {
    59	        var respuesta = await LlamarAsync(estado, cancellationToken);
    60	        _uso.Sumar(respuesta.Uso);
    61	        estado.Invocaciones += respuesta.Llamadas.Count;
    62	        var terminal = Terminal(estado, respuesta);
    63	        return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
