     3	public sealed class PresupuestoDiario
     4	{
     5	    private readonly Lock _candado = new();
     6	    private readonly IReloj _reloj;
     7	    private readonly LimitesAsistente _limites;
     8	    private DateOnly _dia;
     9	    private decimal _gastado;
    10	    private decimal _reservado;
    11	
    12	    public PresupuestoDiario(IReloj reloj, LimitesAsistente limites)
    13	    {
    14	        _reloj = reloj;
    15	        _limites = limites;
    16	        _dia = DiaActual();
    17	    }
    18	
    19	    public bool TryReservar(decimal reservaUsd)
    20	    {
    21	        lock (_candado)
    22	        {
    23	            ReiniciarSiCambioElDia();
    24	            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
    25	            if (_gastado + _reservado + reserva > _limites.PresupuestoDiarioUsd)
    26	            {
    27	                return false;
    28	            }
    29	
    30	            _reservado += reserva;
    31	            return true;
    32	        }
    33	    }
    34	
    35	    public void Sustituir(decimal reservaUsd, decimal costoRealUsd)
    36	    {
    37	        lock (_candado)
    38	        {
    39	            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
    40	            _reservado = Math.Max(0m, _reservado - reserva);
    41	            ReiniciarSiCambioElDia();
    42	            _gastado += costoRealUsd;
    43	        }
    44	    }
    45	
    46	    private DateOnly DiaActual() => DateOnly.FromDateTime(_reloj.AhoraUtc.UtcDateTime);
    47	
    48	    private void ReiniciarSiCambioElDia()
    49	    {
    50	        var hoy = DiaActual();
    51	        if (hoy == _dia)
    52	        {
    53	            return;
    54	        }
    55	
    56	        _dia = hoy;
    57	        _gastado = 0m;
    58	    }
    59	}
