    23	        string respuesta,
    24	        IReadOnlyCollection<string> textosConfidenciales,
    25	        IReadOnlyCollection<string> textosEntregados)
    26	    {
    27	        var permitidos = TextosFijos().Concat(textosEntregados).SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
    28	        var confidenciales = textosConfidenciales.SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
