    16	    private const int FinCirculadosDigitos = 0x2468;
    17	    private const int InicioCirculadasMayusculas = 0x24B6;
    18	    private const int FinCirculadasMayusculas = 0x24CF;
    19	    private const int InicioCirculadasMinusculas = 0x24D0;
    20	    private const int FinCirculadasMinusculas = 0x24E9;
    21	    private const int InicioSubindices = 0x2080;
    22	    private const int FinSubindices = 0x2089;
    23	    private const int InicioSuperindicesCuatroANueve = 0x2074;
    24	    private const int FinSuperindicesCuatroANueve = 0x2079;
