    71	        var porNombre = MencionesDeNombre(tokens, directorio).Where(mencion => !ambito.ClavesDeNombre.Contains(mencion.Clave));
    72	        var terceros = porId.Concat(porNombre).OrderByDescending(mencion => mencion.Inicio).ToList();
    73	        return Reemplazar(pregunta, terceros);
    74	    }
