    86	        foreach (var mencion in mencionesDeFinAInicio.Where(mencion => mencion.Fin <= limite))
    87	        {
    88	            texto = string.Concat(texto.AsSpan(0, mencion.Inicio), MarcadorTercero, texto.AsSpan(mencion.Fin));
    89	            limite = mencion.Inicio;
