    15	    private static readonly IReadOnlyDictionary<char, char> SinAcento = ConstruirTablaSinAcento(
    16	        ('a', "áàäâãåāăą"),
    17	        ('e', "éèëêēėęě"),
    18	        ('i', "íìïîīįı"),
