    25	    public static IReadOnlyList<TokenTexto> Tokenizar(string texto)
    26	    {
    27	        var acumulador = new AcumuladorTokens();
    28	        var inicio = 0;
    29	        foreach (var rune in texto.EnumerateRunes())
    30	        {
    31	            var fin = inicio + rune.Utf16SequenceLength;
    32	            ProcesarRune(acumulador, rune, inicio, fin);
    33	            inicio = fin;
    34	        }
    35	
    36	        acumulador.Cerrar();
    37	        return acumulador.Tokens;
    38	    }
