    40	    public static int BuscarSecuencia(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia)
    41	    {
    42	        for (var indice = 0; indice + secuencia.Count <= tokens.Count; indice++)
    43	        {
    44	            if (CoincideEn(tokens, indice, secuencia))
    45	            {
    46	                return indice;
    47	            }
    48	        }
    49	
    50	        return -1;
    51	    }
