    53	    public static string Plegado(string texto) =>
    54	        string.Concat(texto.EnumerateRunes()
    55	            .SelectMany(PlegadoCompatibilidad.De)
    56	            .Where(caracter => !EsIgnorable(caracter))
    57	            .Select(Plegar));
