    65	    private static void ProcesarRune(AcumuladorTokens acumulador, Rune rune, int inicio, int fin)
    66	    {
    67	        foreach (var caracter in PlegadoCompatibilidad.De(rune))
    68	        {
    69	            Procesar(acumulador, caracter, inicio, fin);
    70	        }
    71	    }
