    73	    private static void Procesar(AcumuladorTokens acumulador, char caracter, int inicio, int fin)
    74	    {
    75	        if (EsIgnorable(caracter))
    76	        {
    77	            acumulador.Extender(fin);
    78	            return;
    79	        }
    80	
    81	        var plegado = Plegar(caracter);
    82	        if (char.IsLetterOrDigit(plegado))
    83	        {
    84	            acumulador.Agregar(plegado, inicio, fin);
    85	            return;
    86	        }
    87	
    88	        acumulador.Cerrar();
    89	    }
