    95	    private static char Plegar(char caracter)
    96	    {
    97	        var sinAnchoCompleto = caracter is >= PrimeroAnchoCompleto and <= UltimoAnchoCompleto
    98	            ? (char)(caracter - DesplazamientoAnchoCompleto)
    99	            : caracter;
   100	        var minuscula = char.ToLowerInvariant(sinAnchoCompleto);
   101	        return SinAcento.GetValueOrDefault(minuscula, minuscula);
   102	    }
