   104	    private static Dictionary<char, char> ConstruirTablaSinAcento(params (char Base, string Variantes)[] grupos) =>
   105	        grupos.SelectMany(grupo => grupo.Variantes.Select(variante => (variante, grupo.Base)))
   106	            .ToDictionary(par => par.variante, par => par.Base);
