   108	    private sealed class AcumuladorTokens
   109	    {
   110	        private readonly List<TokenTexto> _tokens = [];
   111	        private readonly StringBuilder _valor = new();
   112	        private int _inicio;
   113	        private int _fin;
   114	
   115	        public IReadOnlyList<TokenTexto> Tokens => _tokens;
   116	
   117	        public void Agregar(char caracter, int inicio, int fin)
   118	        {
   119	            if (_valor.Length == 0)
   120	            {
   121	                _inicio = inicio;
   122	            }
   123	
   124	            _valor.Append(caracter);
   125	            _fin = fin;
   126	        }
   127	
   128	        public void Extender(int fin)
   129	        {
   130	            if (_valor.Length > 0)
   131	            {
   132	                _fin = fin;
   133	            }
   134	        }
   135	
   136	        public void Cerrar()
   137	        {
   138	            if (_valor.Length == 0)
   139	            {
   140	                return;
   141	            }
   142	
   143	            _tokens.Add(new TokenTexto(_valor.ToString(), _inicio, _fin));
   144	            _valor.Clear();
   145	        }
   146	    }
