    12	    private const int FinAlfabetosMatematicos = 0x1D6A3;
    13	    private const int InicioDigitosMatematicos = 0x1D7CE;
    14	    private const int FinDigitosMatematicos = 0x1D7FF;
    15	    private const int InicioCirculadosDigitos = 0x2460;
    16	    private const int FinCirculadosDigitos = 0x2468;
    17	    private const int InicioCirculadasMayusculas = 0x24B6;
    18	    private const int FinCirculadasMayusculas = 0x24CF;
    19	    private const int InicioCirculadasMinusculas = 0x24D0;
    20	    private const int FinCirculadasMinusculas = 0x24E9;
    21	    private const int InicioSubindices = 0x2080;
    22	    private const int FinSubindices = 0x2089;
    23	    private const int InicioSuperindicesCuatroANueve = 0x2074;
    24	    private const int FinSuperindicesCuatroANueve = 0x2079;
    25	    private const int CuatroComoDigito = 4;
    26	
    27	    private static readonly RangoPlegado[] Rangos =
    28	    [
    29	        new(InicioAlfabetosMatematicos, FinAlfabetosMatematicos, LetraMatematica),
    30	        new(InicioDigitosMatematicos, FinDigitosMatematicos, DigitoMatematico),
    31	        new(InicioCirculadosDigitos, FinCirculadosDigitos, valor => Digito(valor - InicioCirculadosDigitos + 1)),
    32	        new(InicioCirculadasMayusculas, FinCirculadasMayusculas, valor => Letra('A', valor - InicioCirculadasMayusculas)),
    33	        new(InicioCirculadasMinusculas, FinCirculadasMinusculas, valor => Letra('a', valor - InicioCirculadasMinusculas)),
    34	        new(InicioSubindices, FinSubindices, valor => Digito(valor - InicioSubindices)),
    35	        new(InicioSuperindicesCuatroANueve, FinSuperindicesCuatroANueve, valor => Digito(valor - InicioSuperindicesCuatroANueve + CuatroComoDigito))
    36	    ];
    37	
    38	    private static readonly Dictionary<int, string> Equivalencias = new()
    39	    {
    40	        [0x00AA] = "a",
    41	        [0x00BA] = "o",
    42	        [0x00B2] = "2",
    43	        [0x00B3] = "3",
    44	        [0x00B9] = "1",
    45	        [0x0132] = "IJ",
    46	        [0x0133] = "ij",
    47	        [0x017F] = "s",
    48	        [0x2070] = "0",
    49	        [0x2071] = "i",
    50	        [0x207F] = "n",
    51	        [0x24EA] = "0",
    52	        [0xFB00] = "ff",
    53	        [0xFB01] = "fi",
    54	        [0xFB02] = "fl",
    55	        [0xFB03] = "ffi",
    56	        [0xFB04] = "ffl",
    57	        [0xFB05] = "st",
    58	        [0xFB06] = "st"
    59	    };
