    61	    public static string De(Rune rune) =>
    62	        Rangos.FirstOrDefault(rango => rango.Contiene(rune.Value))?.Plegar(rune.Value)
    63	        ?? Equivalencias.GetValueOrDefault(rune.Value)
    64	        ?? rune.ToString();
