    66	    private static string LetraMatematica(int valor)
    67	    {
    68	        var posicion = (valor - InicioAlfabetosMatematicos) % LetrasPorEstilo;
    69	        return posicion < LetrasPorAlfabeto ? Letra('A', posicion) : Letra('a', posicion - LetrasPorAlfabeto);
