   140	using System.ClientModel;
   141	using System.ClientModel.Primitives;
   142	using System.Text.Json;
   143	using Microsoft.Extensions.AI;
   144	using OpenAI;
   145	using TutorFlow.Core.Asistente;
   146	
   147	namespace TutorFlow.Infrastructure.Llm;
   148	
   149	public sealed class ClienteLlmCompatibleOpenAi : IClienteLlm
   150	{
   151	    private const string LlaveParaServidoresSinAutenticacion = "sin-llave";
   152	    private const string SegmentoDeVersion = "v1/";
   153	    private const int ReintentosMaximos = 0;
   154	
   155	    private readonly IChatClient _cliente;
   156	    private readonly string _modelo;
   157	
   158	    public ClienteLlmCompatibleOpenAi(HttpClient httpClient, ProveedorResuelto proveedor, string? llave)
   159	    {
   160	        _modelo = proveedor.Modelo;
   161	        var opciones = new OpenAIClientOptions
   162	        {
   163	            Endpoint = ConstruirEndpoint(proveedor.UrlBase),
   164	            Transport = new HttpClientPipelineTransport(httpClient),
   165	            RetryPolicy = new ClientRetryPolicy(ReintentosMaximos)
   166	        };
   167	        var credencial = new ApiKeyCredential(string.IsNullOrWhiteSpace(llave) ? LlaveParaServidoresSinAutenticacion : llave);
   168	        _cliente = new OpenAIClient(credencial, opciones).GetChatClient(proveedor.Modelo).AsIChatClient();
   169	    }
   170	
   171	    public async Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
   172	    {
   173	        var opciones = new ChatOptions
   174	        {
   175	            ModelId = _modelo,
   176	            MaxOutputTokens = solicitud.MaximoTokensSalida,
   177	            Tools = [.. solicitud.Herramientas.Select(Declarar)]
   178	        };
   179	        try
   180	        {
   181	            var respuesta = await _cliente.GetResponseAsync(Mensajes(solicitud), opciones, cancellationToken);
   182	            return Traducir(respuesta);
   183	        }
   184	        catch (ClientResultException)
   185	        {
   186	            throw new DependenciaNoDisponibleException("El proveedor del LLM respondió con un error.");
   187	        }
   188	    }
   189	
   190	    private static Uri ConstruirEndpoint(string urlBase)
   191	    {
   192	        var raiz = new Uri(urlBase.TrimEnd('/') + "/");
   193	        return raiz.AbsolutePath == "/" ? new Uri(raiz, SegmentoDeVersion) : raiz;
   194	    }
   195	
   196	    private static List<ChatMessage> Mensajes(SolicitudLlm solicitud)
   197	    {
   198	        var mensajes = new List<ChatMessage> { new(ChatRole.System, solicitud.PromptSistema) };
   199	        mensajes.AddRange(solicitud.Mensajes.Select(Mensaje));
   200	        return mensajes;
   201	    }
   202	
   203	    private static ChatMessage Mensaje(MensajeLlm mensaje) => mensaje.Rol switch
   204	    {
   205	        RolMensaje.Herramienta => new ChatMessage(ChatRole.Tool, [new FunctionResultContent(mensaje.IdLlamada ?? string.Empty, mensaje.Contenido)]),
   206	        RolMensaje.Asistente => MensajeDeAsistente(mensaje),
   207	        _ => new ChatMessage(ChatRole.User, mensaje.Contenido)
   208	    };
   209	
   210	    private static ChatMessage MensajeDeAsistente(MensajeLlm mensaje)
   211	    {
   212	        var contenidos = new List<AIContent>();
   213	        if (!string.IsNullOrEmpty(mensaje.Contenido))
   214	        {
   215	            contenidos.Add(new TextContent(mensaje.Contenido));
   216	        }
   217	
   218	        contenidos.AddRange(mensaje.Llamadas.Select(llamada =>
   219	            new FunctionCallContent(llamada.Id, llamada.Nombre, ArgumentosDe(llamada.ArgumentosJson))));
   220	        return new ChatMessage(ChatRole.Assistant, contenidos);
   221	    }
   222	
   223	    private static Dictionary<string, object?> ArgumentosDe(string argumentosJson)
   224	    {
   225	        using var documento = JsonDocument.Parse(argumentosJson);
   226	        return documento.RootElement.ValueKind == JsonValueKind.Object
   227	            ? documento.RootElement.EnumerateObject().ToDictionary(p => p.Name, p => (object?)p.Value.Clone())
   228	            : [];
   229	    }
   230	
   231	    private static AIFunctionDeclaration Declarar(HerramientaLlm herramienta)
   232	    {
   233	        var propiedades = herramienta.Parametros.ToDictionary(
   234	            parametro => parametro.Nombre,
   235	            parametro => new { type = "string", description = parametro.Descripcion });
   236	        var esquema = JsonSerializer.SerializeToElement(new
   237	        {
   238	            type = "object",
   239	            properties = propiedades,
   240	            required = herramienta.Parametros.Where(p => p.Requerido).Select(p => p.Nombre).ToArray()
   241	        });
   242	        return AIFunctionFactory.CreateDeclaration(herramienta.Nombre, herramienta.Descripcion, esquema);
   243	    }
   244	
   245	    private static RespuestaLlm Traducir(ChatResponse respuesta)
   246	    {
   247	        var rechazada = EsRechazo(respuesta);
   248	        var texto = rechazada ? null : respuesta.Text;
   249	        return new RespuestaLlm(
   250	            string.IsNullOrEmpty(texto) ? null : texto,
   251	            LlamadasDe(respuesta),
   252	            UsoDe(respuesta.Usage),
   253	            rechazada);
   254	    }
   255	
   256	    private static bool EsRechazo(ChatResponse respuesta) =>
   257	        respuesta.FinishReason == ChatFinishReason.ContentFilter
   258	        || (respuesta.RawRepresentation is OpenAI.Chat.ChatCompletion completado && !string.IsNullOrEmpty(completado.Refusal));
   259	
   260	    private static List<LlamadaHerramienta> LlamadasDe(ChatResponse respuesta) =>
   261	        [.. respuesta.Messages
   262	            .SelectMany(mensaje => mensaje.Contents)
   263	            .OfType<FunctionCallContent>()
   264	            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>())))];
   265	
   266	    private static UsoTokens UsoDe(UsageDetails? uso) =>
   267	        new((int)(uso?.InputTokenCount ?? 0), (int)(uso?.OutputTokenCount ?? 0));
   268	}
