input.command:
cd "C:/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad/sec" && cat > run.mjs <<'EOF'
import fs from 'fs';
const casos = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const delay = ms => new Promise(r => setTimeout(r, ms));
for (const c of casos) {
  const t0 = Date.now();
  const headers = {'Content-Type': c.ct ?? 'application/json'};
  const body = c.raw ?? JSON.stringify({pregunta: c.p, usuario: {rol: c.rol, id: c.id}});
  try {
    const r = await fetch('http://localhost:8080/api/asistente/preguntar', {method:'POST', headers, body});
    const txt = await r.text();
